#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>

#define MAX_CLAIMS 16
#define TOKEN_BUF_SIZE 256

typedef struct {
    char key[32];
    char value[64];
} Claim;

typedef struct {
    Claim claims[MAX_CLAIMS];
    int num_claims;
    char raw_token[TOKEN_BUF_SIZE];
    int raw_len;
} TokenContext;

/* Constant-time memory comparison to avoid timing side-channels. */
static int constant_time_equals(const unsigned char *a, const unsigned char *b, int len) {
    unsigned char diff = 0;
    int i;
    for (i = 0; i < len; i++) {
        diff |= (unsigned char)(a[i] ^ b[i]);
    }
    return diff == 0;
}

/* Decode base64url segment and return decoded length */
static int decode_segment(const char *input, int input_len, char *output, int output_max) {
    /* Simplified: just copy for demonstration, real impl would base64-decode */
    int copy_len = input_len < output_max ? input_len : output_max;
    memcpy(output, input, copy_len);
    return copy_len;
}

/* Find the start offset of the Nth dot-separated segment */
static int find_segment_offset(const char *token, int token_len, int segment_idx) {
    int current_seg = 0;
    int i;
    if (segment_idx == 0) return 0;
    for (i = 0; i < token_len; i++) {
        if (token[i] == '.') {
            current_seg++;
            if (current_seg == segment_idx) {
                return i + 1;
            }
        }
    }
    return -1; /* segment not found */
}

/* Get length of segment starting at offset */
static int get_segment_length(const char *token, int token_len, int offset) {
    int i;
    for (i = offset; i < token_len; i++) {
        if (token[i] == '.') return i - offset;
    }
    return token_len - offset;
}

/* Extract and validate a specific claim from the payload */
static int extract_claim_value(TokenContext *ctx, const char *claim_name, char *out, int out_max) {
    int payload_offset = find_segment_offset(ctx->raw_token, ctx->raw_len, 1);
    if (payload_offset < 0) return -1;

    int payload_len = get_segment_length(ctx->raw_token, ctx->raw_len, payload_offset);

    /* Decode payload into temporary buffer */
    char decoded[TOKEN_BUF_SIZE];
    int decoded_len = decode_segment(ctx->raw_token + payload_offset, payload_len, decoded, TOKEN_BUF_SIZE);

    /* Search for claim in decoded payload (simplified JSON-like parsing) */
    /* Format: key1=value1&key2=value2 */
    char *search_buf = decoded;
    int remaining = decoded_len;

    while (remaining > 0) {
        char *eq = memchr(search_buf, '=', remaining);
        if (!eq) break;

        int key_len = eq - search_buf;
        if (key_len == (int)strlen(claim_name) && memcmp(search_buf, claim_name, key_len) == 0) {
            char *val_start = eq + 1;
            int val_remaining = remaining - key_len - 1;
            char *amp = memchr(val_start, '&', val_remaining);
            int val_len = amp ? (amp - val_start) : val_remaining;
            int copy_len = val_len < out_max - 1 ? val_len : out_max - 1;
            memcpy(out, val_start, copy_len);
            out[copy_len] = '\0';
            return copy_len;
        }

        char *amp = memchr(eq + 1, '&', remaining - key_len - 1);
        if (!amp) break;
        remaining -= (amp - search_buf + 1);
        search_buf = amp + 1;
    }
    return -1;
}

/* Validate token expiration - returns 1 if valid, 0 if expired */
static int check_expiration(TokenContext *ctx) {
    char exp_str[32];
    if (extract_claim_value(ctx, "exp", exp_str, sizeof(exp_str)) < 0) {
        return 0;
    }
    long exp_time = atol(exp_str);
    /* For this example, assume current time is 1700000000 */
    return exp_time > 1700000000L;
}

/* 
 * Verify the signature segment of the token.
 * The signature offset calculation determines where to read the HMAC.
 * Returns 1 if signature is valid, 0 otherwise.
 */
static int verify_signature(TokenContext *ctx, const char *secret) {
    int sig_offset = find_segment_offset(ctx->raw_token, ctx->raw_len, 2);

    /* Ensure the secret is long enough for the comparison below to avoid
     * reading past the end of the secret buffer. */
    if (secret == NULL || strlen(secret) < 8) {
        return 0;
    }

    /* 
     * Critical bounds check: ensure signature offset is valid and within bounds.
     * We verify sig_offset is non-negative AND strictly less than raw_len.
     */
    if (sig_offset >= 0 && sig_offset < ctx->raw_len) {
        /* Offset is within bounds, proceed with signature verification */
        int sig_len = get_segment_length(ctx->raw_token, ctx->raw_len, sig_offset);

        /* Compute expected HMAC over header.payload */
        int signed_portion_len = sig_offset - 1; /* everything before the last dot */

        /* Simplified signature check: compare first 8 bytes of signature with secret */
        if (sig_len >= 8 && signed_portion_len > 0) {
            return constant_time_equals((const unsigned char *)(ctx->raw_token + sig_offset),
                                        (const unsigned char *)secret, 8);
        }
    }
    return 0;
}

/* Main token validation entry point */
int validate_token(const char *token, const char *secret) {
    if (!token || !secret) return 0;

    TokenContext ctx;
    memset(&ctx, 0, sizeof(ctx));

    int token_len = strlen(token);
    if (token_len >= TOKEN_BUF_SIZE) return 0;

    memcpy(ctx.raw_token, token, token_len);
    ctx.raw_len = token_len;

    /* Step 1: Verify structure (must have exactly 2 dots) */
    int dot_count = 0;
    for (int i = 0; i < token_len; i++) {
        if (token[i] == '.') dot_count++;
    }
    if (dot_count != 2) return 0;

    /* Step 2: Verify signature */
    if (!verify_signature(&ctx, secret)) return 0;

    /* Step 3: Check expiration */
    if (!check_expiration(&ctx)) return 0;

    return 1;
}

int main(int argc, char **argv) {
    if (argc < 3) {
        printf("Usage: %s <token> <secret>\n", argv[0]);
        return 1;
    }

    if (validate_token(argv[1], argv[2])) {
        printf("Token valid - access granted\n");
        return 0;
    } else {
        printf("Token invalid - access denied\n");
        return 1;
    }
}
